def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    out = [row[:] for row in grid]
    # Find a full uniform separator line (horizontal or vertical).
    divs = []
    for r in range(h):
        if len(set(grid[r])) == 1 and grid[r][0] != bg:
            divs.append(('h', r, grid[r][0]))
    for c in range(w):
        vals = {grid[r][c] for r in range(h)}
        if len(vals) == 1 and next(iter(vals)) != bg:
            divs.append(('v', c, next(iter(vals))))
    if not divs:
        return out
    # Divider color is the unique non-background full-length line color.
    orient, d, dc = divs[0]
    pts = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
           if grid[r][c] != bg and grid[r][c] != dc]
    if not pts:
        return out
    if orient == 'h':
        lo, hi = min(r for r,c,v in pts), max(r for r,c,v in pts)
        shift = (d - 1 - hi) if hi < d else (d + 1 - lo)
        moved = [(r + shift, c, v) for r,c,v in pts]
        for r,c,v in pts: out[r][c] = bg
        for r,c,v in moved:
            if 0 <= r < h: out[r][c] = v
        line = min(r for r,c,v in moved) - 1 if hi < d else max(r for r,c,v in moved) + 1
        if 0 <= line < h: out[line] = [8] * w
    else:
        lo, hi = min(c for r,c,v in pts), max(c for r,c,v in pts)
        shift = (d - 1 - hi) if hi < d else (d + 1 - lo)
        moved = [(r, c + shift, v) for r,c,v in pts]
        for r,c,v in pts: out[r][c] = bg
        for r,c,v in moved:
            if 0 <= c < w: out[r][c] = v
        line = min(c for r,c,v in moved) - 1 if hi < d else max(c for r,c,v in moved) + 1
        if 0 <= line < w:
            for r in range(h): out[r][line] = 8
    return out
